#include <bits/stdc++.h>
using namespace std;

const int INF = INT_MAX;
const int MAXN = 10001;

struct Solver {
    struct Edge {
        int to, nxt, cap, cost;
    };

    vector<Edge> edges;
    vector<int> head;
    int nodes;
    vector<int> dist, potential, level, it;
    vector<char> used;

    Solver() : nodes(0), head(MAXN, -1), dist(MAXN), potential(MAXN, 0),
               level(MAXN), it(MAXN), used(MAXN) {}

    int addNodes(int cnt) {
        while (cnt--) head[nodes++] = -1;
        return nodes - 1;
    }

    void addEdge(int u, int v, int cap, int cost) {
        edges.push_back({v, head[u], cap, cost});
        head[u] = (int)edges.size() - 1;
        edges.push_back({u, head[v], 0, -cost});
        head[v] = (int)edges.size() - 1;
    }

    bool dijkstra(int s, int t) {
        fill(dist.begin(), dist.begin() + nodes, INF);
        fill(used.begin(), used.begin() + nodes, 0);

        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
        dist[s] = 0;
        pq.push({0, s});

        while (!pq.empty()) {
            auto [du, u] = pq.top();
            pq.pop();
            if (used[u]) continue;
            used[u] = 1;

            for (int i = head[u]; i != -1; i = edges[i].nxt) {
                Edge &e = edges[i];
                int v = e.to;
                if (!e.cap || used[v]) continue;

                int nd = du + potential[u] + e.cost - potential[v];
                if (dist[v] > nd) {
                    dist[v] = nd;
                    pq.push({nd, v});
                }
            }
        }
        return used[t];
    }

    bool buildLevelGraph(int s, int t) {
        fill(level.begin(), level.begin() + nodes, 0);
        queue<int> q;
        q.push(s);
        level[s] = 1;

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            for (int i = head[u]; i != -1; i = edges[i].nxt) {
                Edge &e = edges[i];
                int v = e.to;
                if (!e.cap || level[v]) continue;

                if (dist[v] == dist[u] + e.cost - potential[v] + potential[u]) {
                    level[v] = level[u] + 1;
                    q.push(v);
                }
            }
        }
        return level[t] != 0;
    }

    int dfs(int u, int t, int f) {
        if (u == t) return f;
        int sent = 0;

        for (int &i = it[u]; i != -1; i = edges[i].nxt) {
            Edge &e = edges[i];
            int v = e.to;

            if (!e.cap || level[v] != level[u] + 1) continue;
            if (dist[v] != dist[u] + e.cost - potential[v] + potential[u]) continue;

            int ret = dfs(v, t, min(f, e.cap));
            if (ret) {
                sent += ret;
                f -= ret;
                e.cap -= ret;
                edges[i ^ 1].cap += ret;
                if (!f) break;
            }
        }
        return sent;
    }

    pair<int,int> minCostFlow(int s, int t, int maxFlow) {
        int totalFlow = 0, totalCost = 0;
        fill(potential.begin(), potential.begin() + nodes, 0);

        while (dijkstra(s, t)) {
            int phaseFlow = 0;

            while (buildLevelGraph(s, t)) {
                fill(it.begin(), it.begin() + nodes, -1);
                int df = dfs(s, t, maxFlow);
                maxFlow -= df;
                phaseFlow += df;
                if (!maxFlow) break;
            }

            totalFlow += phaseFlow;
            totalCost += (dist[t] + potential[t]) * phaseFlow;

            for (int i = 0; i < nodes; ++i)
                if (dist[i] != INF) potential[i] += dist[i];

            if (!maxFlow) break;
        }

        return {totalFlow, totalCost};
    }
};

int main() {
    int n, m, k, c, d;
    scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);

    Solver solver;
    int L = max(n, k) * 2;

    solver.addNodes(L * n);
    int s = solver.addNodes(1);
    int t = solver.addNodes(1);

    for (int j = 0; j < k; ++j) {
        int a;
        scanf("%d", &a);
        --a;
        solver.addEdge(s, a, 1, 0);
    }

    for (int z = 0; z < m; ++z) {
        int u, v;
        scanf("%d %d", &u, &v);
        --u;
        --v;

        for (int i = 0; i + 1 < L; ++i) {
            int u1 = u + i * n;
            int v1 = v + (i + 1) * n;
            int u2 = u + (i + 1) * n;
            int v2 = v + i * n;

            for (int j = 0; j < k; ++j) {
                int w = c + d * (2 * j + 1);
                solver.addEdge(u1, v1, 1, w);
                solver.addEdge(v2, u2, 1, w);
            }
        }
    }

    for (int i = 0; i + 1 < L; ++i) {
        for (int j = 0; j < n; ++j) {
            int u = j + i * n;
            int v = j + (i + 1) * n;
            solver.addEdge(u, v, INF, c);
        }
    }

    for (int i = 0; i < L; ++i)
        solver.addEdge(i * n, t, INF, 0);

    printf("%d\n", solver.minCostFlow(s, t, INF).second);
    return 0;
}
